const CC_INDEX = {}, NAME_INDEX = {};
for (const c of COUNTRIES) { CC_INDEX[c.cc] = c; NAME_INDEX[c.iso.toLowerCase()] = c; for (const n of c.names) NAME_INDEX[n] = c; }

const digitsOf = v => (v == null ? '' : v).toString().replace(/\D/g, '');
function countryByCode(d) { for (const len of [3, 2, 1]) { const c = CC_INDEX[d.slice(0, len)]; if (c) return c; } return null; }
function countryByName(v) { return NAME_INDEX[(v == null ? '' : v).toString().toLowerCase().replace(/[^a-z ]/g, '').trim()] || null; }

// Returns { e164, reason }. countryHint (optional Sheet1 "Country") is used only for numbers without + / 00.
function toE164(raw, countryHint) {
  const str = (raw == null ? '' : raw).toString().trim().replace(/^'+/, '');
  let d = digitsOf(str);
  if (!d) return { e164: null, reason: 'no phone number' };
  const intl = /^(\+|00)/.test(str);
  if (/^00/.test(str)) d = d.slice(2);
  if (d.length > 15) { // repair a duplicated country code, e.g. 9191XXXXXXXXXX
    for (let n = 3; n >= 1; n--) {
      if (d.slice(0, n) === d.slice(n, 2 * n) && d.length - 2 * n >= 7 && d.length - 2 * n <= 12) { d = d.slice(n); break; }
    }
  }
  if (!intl) {
    const hint = countryHint ? countryByName(countryHint) : null;
    if (hint && hint.cc !== '1') { d = d.replace(/^0+/, ''); if (!d.startsWith(hint.cc)) d = hint.cc + d; }
    else if (d.length === 10) d = '1' + d; // bare 10 digits with no country: assumed US/Canada
  }
  if (d.startsWith('1')) {
    return d.length === 11 && /[2-9]/.test(d[1]) ? { e164: '+' + d, reason: '' } : { e164: null, reason: 'invalid US/Canada number' };
  }
  if (!countryByCode(d)) return { e164: null, reason: 'unknown country code' };
  if (d.length < 8 || d.length > 15) return { e164: null, reason: 'invalid number length' };
  return { e164: '+' + d, reason: '' };
}
function validZone(z) { try { return !!z && DateTime.utc().setZone(z).isValid; } catch (e) { return false; } }
function parseZones(v) {
  const zs = (v == null ? '' : v).toString().split(/[|,]/).map(z => z.trim()).filter(Boolean);
  return zs.length && zs.every(validZone) ? zs : null;
}
// Returns { zones: [IANA...] | null, source }
function zonesFor(e164, override) {
  const o = parseZones(override);
  if (o) return { zones: o, source: 'Timezone column' };
  if (!e164) return { zones: null, source: 'no valid phone' };
  const d = e164.replace(/^\+/, '');
  if (d.startsWith('1')) {
    const tz = NANP_TZ[d.slice(1, 4)];
    return tz ? { zones: [tz], source: 'area code' } : { zones: NANP_FALLBACK, source: 'US/Canada overlap (unknown area code)' };
  }
  if (AU_PREFIX[d.slice(0, 3)]) return { zones: AU_PREFIX[d.slice(0, 3)], source: 'area code' };
  const c = countryByCode(d);
  if (!c) return { zones: null, source: 'unknown country code' };
  if (!c.zones) return { zones: null, source: `${c.iso} spans many time zones - fill the Timezone column` };
  return { zones: c.zones, source: c.zones.length > 1 ? `${c.iso} overlap of ${c.zones.length} zones` : 'country' };
}
function isWorkday(localDt, zone) {
  return FRI_SAT_WEEKEND.has(zone) ? (localDt.weekday !== 5 && localDt.weekday !== 6) : localDt.weekday <= 5;
}
function isCallable(dtUtc, zones) {
  return zones.every(z => { const l = dtUtc.setZone(z); return isWorkday(l, z) && l.hour >= CALL_WINDOW.start && l.hour < CALL_WINDOW.end; });
}
// First callable moment >= fromUtc (15-minute steps, handles :30/:45 offsets and DST). ISO UTC string or null.
function nextCallable(fromUtc, zones) {
  let d = fromUtc.toUTC();
  if (isCallable(d, zones)) return d.toISO();
  d = d.set({ minute: Math.floor(d.minute / 15) * 15, second: 0, millisecond: 0 });
  for (let i = 0; i < 4 * 24 * 10; i++) { d = d.plus({ minutes: 15 }); if (isCallable(d, zones)) return d.toISO(); }
  return null;
}
// ---- end shared helpers ----

// Decides, for the whole sheet, what (if anything) to do this run:
//  - marks stale in-flight rows, blocks DNC, defers out-of-window rows with a real Next Attempt At,
//  - dispatches at most MAX_IN_FLIGHT calls in total (one at a time by default).
const MAX_IN_FLIGHT = 1;
const MAX_ATTEMPTS = 4;     // total dials per lead (initial + 3 retries); must match the listener
const STALE_MINUTES = 30;   // Dispatched/Dispatching with no webhook after this -> manual check
const AGENT_ID = Number($env.OMNIDIM_AGENT_ID || 0);
const now = DateTime.utc();
const DUE = ['Ready to Dispatch', 'Awaiting Calling Window'];
const IN_FLIGHT = ['Dispatched', 'Dispatching'];
const S = v => (v == null ? '' : v).toString().trim();

const dnc = new Set($('Read DNC List').all().map(i => digitsOf(i.json['Phone Number'])).filter(Boolean));
const rows = $input.all().map(i => i.json).filter(r => r && r.row_number);
for (const r of rows) if (S(r['Call Status']) === 'Do Not Call') { const d = digitsOf(r['Phone Number']); if (d) dnc.add(d); }

const out = [];
const upd = (r, status, next) => out.push({ json: { action: 'update', row_number: r.row_number,
  new_status: status, next_attempt_at: next == null ? S(r['Next Attempt At']) : next } });

let inFlight = 0;
const busy = new Set();
for (const r of rows) {
  if (!IN_FLIGHT.includes(S(r['Call Status']))) continue;
  const at = DateTime.fromISO(S(r['Dispatched At']), { zone: 'utc' });
  if (!at.isValid || now.diff(at, 'minutes').minutes > STALE_MINUTES) { upd(r, 'Stale - No Webhook - Check Manually', null); continue; }
  inFlight++; busy.add(digitsOf(r['Phone Number']));
}

const eligible = [];
for (const r of rows) {
  if (!DUE.includes(S(r['Call Status']))) continue;
  const phone = toE164(r['Phone Number']).e164;
  if (!phone) { upd(r, 'Needs Manual Review - invalid phone', ''); continue; }
  const geo = zonesFor(phone, r['Timezone']);
  if (!geo.zones) { upd(r, 'Needs Manual Review - set Timezone', ''); continue; }
  if (dnc.has(digitsOf(phone))) { upd(r, 'Do Not Call', ''); continue; }
  if (!S(r['Grounded Solution'])) { upd(r, 'Needs Manual Review - insufficient verified content', ''); continue; }
  const attempts = parseInt(r['Retry Count'], 10) || 0;
  const cap = S(r['Outcome']) === 'Callback Requested' ? MAX_ATTEMPTS + 1 : MAX_ATTEMPTS;
  if (attempts >= cap) { upd(r, 'No Answer - Max Retries Reached', ''); continue; }
  const nextRaw = S(r['Next Attempt At']);
  let dueAt = now;
  if (nextRaw) {
    const t = DateTime.fromISO(nextRaw, { zone: 'utc' });
    if (!t.isValid) { upd(r, 'Needs Manual Review - invalid Next Attempt At', nextRaw); continue; }
    if (t > now) continue;          // not due yet
    dueAt = t;
  }
  if (!isCallable(now, geo.zones)) {
    const n = nextCallable(now, geo.zones);
    if (!n) { upd(r, 'Needs Manual Review - no shared calling hours, set Timezone', ''); continue; }
    if (n && n !== nextRaw) upd(r, 'Awaiting Calling Window', n);
    continue;
  }
  if (busy.has(digitsOf(phone))) continue;  // same number already on a call
  eligible.push({ r, phone, attempts, dueAt });
}

eligible.sort((a, b) => (a.dueAt.toMillis() - b.dueAt.toMillis()) || (a.r.row_number - b.r.row_number));
const slots = Math.max(0, MAX_IN_FLIGHT - inFlight);
const picked = new Set();
for (const e of eligible) {
  if (picked.size >= slots) break;
  if (picked.has(digitsOf(e.phone))) continue;
  picked.add(digitsOf(e.phone));
  const r = e.r;
  out.push({ json: {
    action: 'dispatch', row_number: r.row_number, attempts_after: e.attempts + 1,
    to_number: e.phone, dispatched_at: now.toISO(),
    dispatch_body: { agent_id: AGENT_ID, to_number: e.phone, call_context: {
            lead_ref: `${r.row_number}-${e.attempts + 1}`,
      company: S(r['Company']), dm_name: S(r['DM Name']), dm_title: S(r['DM Title']),
      key_pain_points: S(r['Key Pain Points']), pain_point_used: S(r['Pain Point Used']),
      competitor_angle: S(r['Competitor Angle']), solution_description: S(r['Grounded Solution'])
    } }
  } });
}
return out;

// Turns the HTTP result into a safe state. Ambiguous outcomes are NEVER retried automatically.
const lead = $('Is Dispatch?').item.json;
const r = $json;
const s = typeof r.statusCode === 'number' ? r.statusCode : null;
let b = r.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const d = b.data || {};
const callId = [b.call_id, b.callId, b.id, b.request_id, d.call_id, d.callId, d.id].find(v => v != null && v !== '');
const err = r.error || null;
const errMsg = err ? (err.message || JSON.stringify(err)).toString().slice(0, 300) : '';
const netCode = err ? (err.code || (err.cause && err.cause.code) || '') : '';
const later = mins => DateTime.utc().plus({ minutes: mins }).toISO();
let status, next = '', refund = false, alert = '';
if (s !== null && s >= 200 && s < 300) {
  status = 'Dispatched';
  if (!callId) console.warn(`[DISPATCH] row=${lead.row_number} 2xx without call id; listener will match by phone. body=${JSON.stringify(b).slice(0, 300)}`);
} else if (s === 429) {
  status = 'Awaiting Calling Window'; next = later(10); refund = true;
} else if (s === 401 || s === 402 || s === 403) {
  status = 'Awaiting Calling Window'; next = later(60); refund = true;
  alert = `OmniDimension rejected the dispatch (HTTP ${s}). Check the API key / account credits. Row ${lead.row_number} rescheduled.`;
} else if (s !== null && s >= 400 && s < 500) {
  status = 'Dispatch Failed - Check Number';
  alert = `OmniDimension rejected row ${lead.row_number} (HTTP ${s}): ${JSON.stringify(b).slice(0, 300)}`;
} else if (['ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN'].includes(netCode)) {
  status = 'Awaiting Calling Window'; next = later(10); refund = true; // request never reached the provider
} else {
  status = 'Dispatch Unknown - Check Manually';
  alert = `Dispatch outcome unknown for row ${lead.row_number} (HTTP ${s === null ? 'none' : s} ${netCode} ${errMsg}). NOT retried to avoid a duplicate call - check OmniDimension call logs.`;
}
return { json: { row_number: lead.row_number, new_status: status, call_id: callId ? String(callId) : '',
  next_attempt_at: next, retry_count: refund ? lead.attempts_after - 1 : lead.attempts_after,
  http_status: s, alert } };
